ng ToUpper(const T& in) {
  auto it = std::cbegin(in);
  auto end = std::cend(in);
  std::string out(std::distance(it, end), 0);
  size_t i;
  for (i = 0; it != end; ++it, ++i) out[i] = ToUpper(*it);
